Bmp581Handler::Bmp581Handler(BaseI2c& bus, const Bmp581HandlerConfig& config,
                             HandlerMutex* bus_mutex) noexcept
    : HandlerBase(bus_mutex), comm_(bus), config_(config) {}

Bmp581Handler::~Bmp581Handler() noexcept {
  DestroyDriver(); // the driver refers to comm_, which is destroyed before HandlerBase
}

Bmp581Diagnostics Bmp581Handler::GetDiagnostics() const noexcept {
  return {Header()};
}

Result<void> Bmp581Handler::initializeLocked() noexcept {
  if (!comm_.EnsureInitialized()) {
    return {Status::DependencyNotReady, static_cast<uint16_t>(comm_.LastBusError())};
  }
  // The driver checks the chip ID; apply config_ here once it has answered.
  return ToResult(EmplaceDriver(comm_).Init());
}

